from . import resources
import logging


logger = logging.getLogger()


class hanging_resources(object):
    """
    Listens for start and stop of test cases.
    This robot listener is for automatically running tests on not freed resources.
    The current used reources are checked with help of taf.ccs.aashell (get_resource_usage)
    The information is retrieved at start of a test case and at the end of a test case.
    With the end of the test case, the used reosurces are compared with each other.
    By default, the test case will fail, if the resources are different.
    This Robot library has an aditional parameter "fail_on_not_released_resources", which his by
    default set to True.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, fail_on_not_released_resources=True):
        """
        Constructs the resource library robot listener

        :param fail_on_not_released_resources: Flag for enabling or disabling the failing of the test case
        """
        pass

    def get_resources_usage(self, node_id=0, node_type='gnb', detailed=False, filename=None):
        """
        This Keyword returns the used resources of the given nodeb.

        TODO: Adapt for supporting short format

        :param node_type: The type of nodeB, can be 'enb' or 'gnb'
        :param node_id: The node_id which corresponds to the index in the testline config of tl.gnbs or tl.enbs
        :param name: Optional, if given, the resource data will be saved to this file
         """
        return resources.get_resources(node_id=node_id, node_type=node_type, detailed=detailed, name=filename)

    def resources_should_be_equal(self, resource1, resource2, exclude=None, save_to_file=None):
        """
        resources.should_be_equal(resource1, resource2, exclude, tc_name)
        This function checks with help of the taf.ccs.aashell library, if the two given resources have differences.

        TODO: Save the resources and result in files constructed by output_dir and tc_name

        :param resource1: The first data for the comparance
        :param resource1: The second data for the comparance
        :param exclude: What params to exclude during comparison. I.e. '//bufferPoolFreeCount'
        :param save_to_file: Optional, if given and resources are different, diff data will be saved to this file.
        """
        return resources.should_be_equal(resource1, resource2, exclude, save_to_file)

    def selected_resources_should_match_comparison(self, resource1, resource2, *args):
        """
        This keyword compares with help of the taf.ccs.aashell library the values of resource1 and
        resource2 in a more specific way. The user can provide specific compare functionality.
        Comparing to keyword compare_resources_with_xpath from taf.ccs.aashell here the default
        excluded paths are also ignored.

        :param resource1: The first data for the comparance
        :param resource1: The second data for the comparance
        :param args: a list of parameters with their comparison function

        Example usage, the ${leaf_nodes} and ${Equality Check} are defined in taf/ccs/aashell/consts.py:

        .. code:: robotframework

            *** Settings ***
            Variables   taf/ccs/aashell/consts.py
            Library     taf.ul.hanging_resources

            *** Keywords ***
            Compare Resources
                [Arguments]   ${resources_before}   ${resources_after}

                ${tolerance_check}=   Evaluate   lambda r1, r2: abs(int(r1)-int(r2)) < 4

                Selected Resources Should Match Comparison   ${resources_before}   ${resources_after}
                ...                                          //numOfResources      ${tolerance_check}
                ...                                          ${leaf_nodes}         ${Equality Check}
        """
        return resources.compare_resources(resource1, resource2, *args)

    def configure_default_excluding_resource_paths(self, add=None, remove=None):
        """
        Configure the default excluding paths by xpath expressions

        :param string add: The xpath to add to the default list of excluding paths
        :param string remove: The xpath to remove from the default list of excluding paths

        Example usage:

        .. code-block:: robotframework

            *** Settings ***
            Library   taf.ul.hanging_resources

            *** Test Cases ***
            Modify the default excluding reosurce paths
                Configure Default Excluding Resource paths
                ...    add=//cellState

        """
        if add:
            logger.warning("Added {}".format(add))
            resources.EXCLUDE_PATHS.add(add)
        if remove:
            resources.EXCLUDE_PATHS.remove(remove)
